/**
 * The resource manifest of an application (`GET /.well-known/strutvane.json`, ADR-0014): what
 * `@strutvane/ui` reads to build its sidebar, tables and forms. This is the "HTTP + manifest"
 * connection of the integration map, so the UI never imports the framework's runtime.
 *
 * **Where the resources come from:** the app's own resource routes, never the list of tables. A
 * resource is in the manifest only when a `ResourceController` serves it under the API base path
 * (`Route.apiResource('customers', CustomerController)`, written by hand or generated by
 * `node strut migrate`). So the manifest never advertises a screen whose API does not exist. Its
 * fields come from `.strutvane/resources.json` (labels, inputs, filters, sorting, relations),
 * falling back to the controller's own metadata when that file is missing.
 *
 * **Per actor, deny by default:** capabilities are the API's own decisions, made with the same
 * policy the controller uses (its `policy`, else the registered or discovered one; none = deny):
 * - `list` and `create`: the route exists and `viewAny` / `create` allows it;
 * - `view`: the route exists and the actor may list (the list only holds rows they may see);
 * - `update`, `delete`: the route exists, the actor may list, and the policy may allow the
 *   ability on some rows (its `before()` allows it outright, or a signed-in actor meets a policy
 *   that defines the method). The API still decides per row; this only says whether to show the
 *   button.
 * A resource the actor can do nothing with is left out, so a guest learns nothing about which
 * resources and fields exist. Hidden and secret fields are never described.
 *
 * @module
 */
import { existsSync, readFileSync } from 'node:fs'
import { join } from 'node:path'
import { allows, type Policy } from '../../auth/gate.ts'
import {
  type FieldDescriptor,
  type FilterOperator,
  type JsonSchema,
  MANIFEST_VERSION,
  type ResourceCapabilities,
  type ResourceDescriptor,
  type ResourceManifest,
} from '../../contracts/index.ts'
import type { AuthUser } from '../../foundation/registry.ts'
import type {
  AppMetadata,
  FieldMetadata,
  ResourceMetadata as GeneratedResource,
} from '../../schema/generate/metadata.ts'
import type { ResourceMetadata } from './resource-model.ts'

/**
 * One resource the app serves, as the manifest needs it.
 *
 * @example
 * const customers: ManifestResource = { path: 'customers', actions: new Set(['index', 'show']), metadata, policy }
 */
export interface ManifestResource {
  /** The path below the API base path (`customers` for `/api/customers`). */
  readonly path: string
  /** The resource actions that have a route (`index`, `store`, `show`, `update`, `destroy`). */
  readonly actions: ReadonlySet<string>
  /** The controller's metadata (table, model name, labels, fields). */
  readonly metadata: ResourceMetadata
  /** The policy in force; `undefined` denies everything. */
  readonly policy: Policy<unknown> | undefined
}

/** Options for {@link buildAppManifest}. */
export interface AppManifestOptions {
  readonly app: { readonly name: string; readonly apiVersion: string }
  readonly resources: readonly ManifestResource[]
  /** `.strutvane/resources.json`, when the app has one. */
  readonly metadata: AppMetadata | undefined
  readonly user: AuthUser | null
  readonly now: () => Date
}

/** `resources.json` filter operators → the manifest's (contracts) operators. */
const OPERATORS: Readonly<Record<string, readonly FilterOperator[]>> = Object.freeze({
  eq: ['eq'],
  ne: ['ne'],
  in: ['in'],
  gt: ['gt'],
  gte: ['gte'],
  lt: ['lt'],
  lte: ['lte'],
  contains: ['contains'],
  startsWith: ['startsWith'],
  null: ['isNull', 'isNotNull'],
})

/** `resources.json` inputs → the manifest's suggested widget. */
const WIDGETS: Readonly<Record<string, string>> = Object.freeze({
  textarea: 'textarea',
  decimal: 'decimal',
  switch: 'switch',
  select: 'select',
  relation: 'relation-picker',
  date: 'date',
  datetime: 'datetime',
  json: 'json',
})

/** Column kinds → manifest field types (the rest keep their own name). */
const TYPES: Readonly<Record<string, string>> = Object.freeze({
  foreignId: 'belongsTo',
  double: 'float',
  timestamp: 'datetime',
})

/** A field name the UI accepts (it ends up in URLs and DOM ids). */
const FIELD_NAME = /^[A-Za-z][A-Za-z0-9_]*$/

/**
 * Build the manifest for one actor.
 *
 * @example
 * const manifest = await buildAppManifest({ app: { name: 'Northwind', apiVersion: '' }, resources, metadata, user: ctx.user, now: () => new Date() })
 */
export async function buildAppManifest(options: AppManifestOptions): Promise<ResourceManifest> {
  const generated = new Map(
    (options.metadata?.resources ?? []).map((resource) => [resource.table, resource]),
  )
  const modelOfTable = new Map(
    (options.metadata?.resources ?? []).map((resource) => [resource.table, resource.model]),
  )
  const described: { readonly order: number; readonly descriptor: ResourceDescriptor }[] = []
  for (const resource of options.resources) {
    const capabilities = await capabilitiesFor(resource, options.user)
    if (!Object.values(capabilities).some(Boolean)) continue
    const full = generated.get(resource.metadata.table)
    const descriptor = describe(resource, full, capabilities, modelOfTable)
    // A resource with no field to show can't be rendered, and the UI refuses a whole manifest
    // with one bad resource in it: leave it out instead of breaking every screen.
    if (descriptor === undefined) continue
    described.push({ order: full?.sidebar.order ?? Number.MAX_SAFE_INTEGER, descriptor })
  }
  described.sort((a, b) => a.order - b.order)
  return {
    manifestVersion: MANIFEST_VERSION,
    app: options.app,
    generatedAt: options.now().toISOString(),
    resources: described.map((entry) => entry.descriptor),
  }
}

/** What this actor may do with a resource (see the module comment for the rules). */
async function capabilitiesFor(
  resource: ManifestResource,
  user: AuthUser | null,
): Promise<ResourceCapabilities> {
  const policy = resource.policy
  const has = (action: string): boolean => resource.actions.has(action)
  if (policy === undefined)
    return {
      list: false,
      view: false,
      create: false,
      update: false,
      delete: false,
      restore: false,
      export: false,
    }
  const list = await allows(policy, 'viewAny', user)
  // A record ability can't be decided without the record. The button shows when the policy can
  // allow it on some row: its before() allows it outright, or a signed-in user meets a policy
  // that defines it. The API decides per row (and answers 403 or 404) either way.
  const onSomeRows = (ability: string): boolean => {
    if (!list) return false
    const early = policy.before?.(user, ability)
    if (early !== undefined) return early === true
    return (
      user !== null && typeof (policy as Readonly<Record<string, unknown>>)[ability] === 'function'
    )
  }
  return {
    list: has('index') && list,
    // Rows the user may list are rows they may open: the list is already filtered for them.
    view: has('show') && list,
    create: has('store') && (await allows(policy, 'create', user)),
    update: has('update') && onSomeRows('update'),
    delete: has('destroy') && onSomeRows('delete'),
    // Restore and export have no resource routes yet (`ResourceController` serves the five
    // API actions); never offer a button whose request would 404.
    restore: false,
    export: false,
  }
}

/** The descriptor of one resource. */
function describe(
  resource: ManifestResource,
  full: GeneratedResource | undefined,
  capabilities: ResourceCapabilities,
  modelOfTable: ReadonlyMap<string, string>,
): ResourceDescriptor | undefined {
  const meta = resource.metadata
  const generatedFields = (full?.fields ?? [])
    .filter((field) => !field.hidden && FIELD_NAME.test(field.name))
    .map((field) => fullField(field, modelOfTable))
  const fields =
    generatedFields.length > 0
      ? generatedFields
      : meta.fields
          .filter((field) => !field.hidden && FIELD_NAME.test(field.name))
          .map((field) => basicField(field))
  const first = fields[0]
  if (first === undefined) return undefined
  const names = new Set(fields.map((field) => field.name))
  const title = full?.titleField ?? meta.primaryKey
  const listed = full?.fields.filter((field) => field.listed && names.has(field.name)) ?? []
  return {
    name: meta.model,
    path: resource.path,
    label: meta.label.singular,
    pluralLabel: meta.label.plural,
    // The UI refuses a title field that is not a described field: fall back to the key.
    titleField: names.has(title) ? title : first.name,
    fields,
    actions: [],
    capabilities,
    softDeletes: full?.softDeletes ?? false,
    tenantScoped: full?.tenant !== undefined,
    audited: false,
    ...(listed.length > 0 ? { ui: { listColumns: listed.map((field) => field.name) } } : {}),
  }
}

/** A field from `resources.json`. */
function fullField(
  field: FieldMetadata,
  modelOfTable: ReadonlyMap<string, string>,
): FieldDescriptor {
  const target = field.references === undefined ? undefined : modelOfTable.get(field.references)
  const widget = WIDGETS[field.input]
  const schema = schemaOf(field.cast, field.maxLength, field.options)
  return {
    name: field.name,
    type:
      field.kind === 'foreignId' && target === undefined
        ? 'integer'
        : (TYPES[field.kind] ?? field.kind),
    label: field.label,
    required: field.required,
    nullable: field.nullable,
    unique: field.unique,
    readOnly: !field.fillable,
    writeOnce: false,
    filterOperators: field.filterOperators.flatMap((op) => OPERATORS[op] ?? []),
    sortable: field.sortable,
    searchable: field.searchable !== false,
    ...(field.options === undefined ? {} : { enumValues: field.options }),
    ...(target === undefined
      ? {}
      : { relation: { kind: 'belongsTo' as const, target, foreignKey: field.name } }),
    ...(widget === undefined ? {} : { widget }),
    ...(schema === undefined ? {} : { schema }),
  }
}

/** A field from the controller's metadata alone (no `resources.json`): nothing filterable. */
function basicField(field: ResourceMetadata['fields'][number]): FieldDescriptor {
  const schema = schemaOf(field.cast, field.maxLength, field.options)
  return {
    name: field.name,
    type: TYPES[field.kind] ?? field.kind,
    label: field.label,
    required: field.required,
    nullable: field.nullable,
    unique: field.unique,
    readOnly: !field.fillable || field.kind === 'id',
    writeOnce: false,
    filterOperators: [],
    sortable: false,
    searchable: false,
    ...(field.options === undefined ? {} : { enumValues: field.options }),
    ...(schema === undefined ? {} : { schema }),
  }
}

/** Client-side validation hints (the API validates again; this only helps forms). */
function schemaOf(
  cast: string,
  maxLength: number | undefined,
  options: readonly string[] | undefined,
): JsonSchema | undefined {
  if (options !== undefined) return { type: 'string', enum: [...options] }
  if (cast === 'string' && maxLength !== undefined) return { type: 'string', maxLength }
  if (cast === 'integer') return { type: 'integer' }
  if (cast === 'boolean') return { type: 'boolean' }
  return undefined
}

/**
 * `.strutvane/resources.json` (written by `node strut migrate`), or `undefined` when the app has
 * none or it is not a version-1 document: the manifest then describes fields from the
 * controllers' own metadata. Read once per app (the dev server restarts when the file changes).
 *
 * @example
 * readAppMetadata('/srv/northwind')?.resources.length // 4
 */
export function readAppMetadata(basePath: string): AppMetadata | undefined {
  const file = join(basePath, '.strutvane', 'resources.json')
  if (!existsSync(file)) return undefined
  let parsed: unknown
  try {
    parsed = JSON.parse(readFileSync(file, 'utf8'))
  } catch {
    return undefined
  }
  if (typeof parsed !== 'object' || parsed === null) return undefined
  const document = parsed as { version?: unknown; resources?: unknown }
  if (document.version !== 1 || !Array.isArray(document.resources)) return undefined
  return parsed as AppMetadata
}

/**
 * The API version named by the API base path (`/api/v1` → `v1`), or `''` when it has none (the
 * default `/api`, CONSISTENCY #33).
 *
 * @example
 * apiVersionOf('/api/v2') // 'v2'
 */
export function apiVersionOf(apiPrefix: string): string {
  return /\/(v\d+)\/?$/.exec(apiPrefix)?.[1] ?? ''
}
